mapper.select:
SELECT h.id, h.user_id, u.username, h.create_time AS changeTime, h.change_ip, h.create_time, h.update_time, h.create_user, h.update_user, cu.username AS create_username, uu.username AS update_username FROM log_user_password_history h LEFT JOIN sys_user_profile u ON h.user_id = u.id LEFT JOIN sys_user_profile cu ON h.create_user = cu.id LEFT JOIN sys_user_profile uu ON h.update_user = uu.id
AND h.user_id = #{query.userId}
AND h.create_time >= #{query.changeTimeStart}
AND h.create_time <= #{query.changeTimeEnd}
AND h.change_ip LIKE CONCAT('%', #{query.changeIp}, '%')
ORDER BY h.create_time DESC
